import { describe, it, expect } from 'vitest'
import { readFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { PRINTABLE_RANGES, PRINTABLE_UNICODE_VERSION } from '../src/printable-table.js'
import { isPrintable, safeName, unsafeName } from '../src/safename.js'

// SafeName's printable test is pinned to Unicode 17.0.0 (decided 2026-11-13
// by the release lead; reversible). The table is generated by
// scripts/gen-printable.mjs from the shared printable-17.0.0.txt, a
// byte-identical copy of c4 core's c4m/testdata/safename-vector file.

const V = fileURLToPath(new URL('./fixtures/safename-vector/', import.meta.url))

async function fileRanges(): Promise<Array<[number, number]>> {
  const text = await readFile(V + `printable-${PRINTABLE_UNICODE_VERSION}.txt`, 'utf8')
  return text.split('\n').map(l => l.trim()).filter(l => l !== '' && !l.startsWith('#')).map(l => {
    const [lo, hi] = l.split('..')
    return [parseInt(lo, 16), parseInt(hi, 16)]
  })
}

describe('printable table pinned to Unicode 17.0.0', () => {
  it('equals the shared text file, every range', async () => {
    const want = await fileRanges()
    expect(want).toHaveLength(741)
    const got: Array<[number, number]> = []
    for (let i = 0; i < PRINTABLE_RANGES.length; i += 2) got.push([PRINTABLE_RANGES[i], PRINTABLE_RANGES[i + 1]])
    expect(got).toEqual(want)
  })

  it('is the version the vector records', async () => {
    expect((await readFile(V + 'unicode-version.txt', 'utf8')).trim()).toBe(PRINTABLE_UNICODE_VERSION)
  })

  it('isPrintable agrees with the file at every range edge', async () => {
    for (const [lo, hi] of await fileRanges()) {
      expect(isPrintable(lo), lo.toString(16)).toBe(true)
      expect(isPrintable(hi), hi.toString(16)).toBe(true)
      expect(isPrintable(lo - 1), (lo - 1).toString(16)).toBe(false)
      expect(isPrintable(hi + 1), (hi + 1).toString(16)).toBe(false)
    }
  })

  it('writes U+0870 (Unicode 14.0) as itself on every runtime', () => {
    const s = String.fromCodePoint(0x0870)
    expect(safeName(s)).toBe(s)
  })

  it('encodes U+0378 (unassigned in 17.0.0) and decodes it back', () => {
    const s = String.fromCodePoint(0x0378)
    const enc = safeName(s)
    // U+0378 is CD B8 in UTF-8, written as braille between currency signs.
    expect(enc).toBe('¤⣍⢸¤')
    expect(unsafeName(enc)).toBe(s)
  })
})
